<?php
namespace App\Livewire\LMS\Subjects;
use App\Models\School; use App\Models\Subject; use Illuminate\Foundation\Auth\Access\AuthorizesRequests; use Illuminate\Validation\Rule; use Illuminate\Validation\ValidationException; use Jantinnerezo\LivewireAlert\Facades\LivewireAlert; use Livewire\Attributes\Layout; use Livewire\Component; use Livewire\WithPagination; use Throwable;
#[Layout('layouts.lms')]
class Index extends Component { use AuthorizesRequests; use WithPagination; public bool $showFormModal=false,$showDeleteModal=false,$isActive=true; public ?int $editingId=null,$deletingId=null; public string $name='',$code='',$description=''; public function mount():void{$this->authorize('viewAny',Subject::class);} public function create():void{$this->authorize('create',Subject::class);$this->resetForm();$this->showFormModal=true;} public function edit(Subject $subject):void{$this->authorize('update',$subject);$this->editingId=$subject->id;$this->name=$subject->name;$this->code=$subject->code??'';$this->description=$subject->description??'';$this->isActive=$subject->is_active;$this->showFormModal=true;}
 public function save():void{$subject=$this->editingId?Subject::findOrFail($this->editingId):null;$this->authorize($subject?'update':'create',$subject??Subject::class);$schoolId=$subject?->school_id??School::query()->value('id');abort_unless($schoolId,422,'Configure a school before creating a subject.');try{$data=$this->validate(['name'=>['required','string','max:150',Rule::unique('subjects','name')->where('school_id',$schoolId)->ignore($subject?->id)],'code'=>['nullable','string','max:50',Rule::unique('subjects','code')->where('school_id',$schoolId)->ignore($subject?->id)],'description'=>['nullable','string','max:2000'],'isActive'=>['boolean']]);Subject::updateOrCreate(['id'=>$subject?->id],['school_id'=>$schoolId,'name'=>$data['name'],'code'=>$data['code']?:null,'description'=>$data['description']?:null,'is_active'=>$data['isActive']]);$this->showFormModal=false;$this->resetForm();LivewireAlert::title($subject?'Subject updated':'Subject created')->success()->asToast()->position('top-end')->show();}catch(ValidationException $e){LivewireAlert::title('Check the form')->error()->asToast()->position('top-end')->show();throw $e;}catch(Throwable $e){report($e);LivewireAlert::title('Unable to save subject')->error()->asToast()->position('top-end')->show();}}
 public function confirmDelete(Subject $subject):void{$this->authorize('delete',$subject);$this->deletingId=$subject->id;$this->showDeleteModal=true;} public function delete():void{$subject=Subject::findOrFail($this->deletingId);$this->authorize('delete',$subject);if($subject->classSubjects()->exists()){$this->addError('delete','Subjects assigned to classes cannot be deleted. Archive the subject instead.');LivewireAlert::title('Subject cannot be deleted')->warning()->asToast()->position('top-end')->show();return;}try{$subject->delete();$this->showDeleteModal=false;$this->deletingId=null;LivewireAlert::title('Subject deleted')->success()->asToast()->position('top-end')->show();}catch(Throwable $e){report($e);LivewireAlert::title('Unable to delete subject')->error()->asToast()->position('top-end')->show();}}
 public function closeModals():void{$this->showFormModal=false;$this->showDeleteModal=false;$this->resetForm();$this->resetErrorBag();} private function resetForm():void{$this->reset(['editingId','deletingId','name','code','description','isActive']);$this->isActive=true;$this->resetValidation();} public function render(){return view('livewire.lms.subjects.index',['subjects'=>Subject::withCount('classSubjects')->orderBy('name')->paginate(15)]);}}
